package studyfix.assignment;

import studyfix.Protocol;
import studyfix.Server;
import studyfix.assignment.protocol.AssignmentJson;
import studyfix.assignment.protocol.AssignmentWire;
import studyfix.assignment.transport.AssignmentTcpServer;

import java.io.*;
import java.net.Socket;
import java.nio.file.*;
import java.util.*;
import java.util.regex.*;

/** Test thật trên localhost cho hai loại bài tập, chấm code chung, bài nộp riêng, cuộc thi và phân quyền cổng 5002. */
public final class AssignmentProtocolIntegrationTest {
 private static int checks;
 private static void check(boolean b,String text){checks++;if(!b)throw new AssertionError(text);}
 public static void main(String[] args)throws Exception{
  Path temp=Files.createTempDirectory("studyfix-p3-e2e-");System.setProperty("studyfix.screen.port","0");
  Server core=null;AssignmentTcpServer assignments=null;Control teacher=null,student1=null,student2=null;
  try{
   core=new Server(0,temp.resolve("core.db"));assignments=new AssignmentTcpServer(core.gateway(),temp.resolve("learning.db"),0,16,1,"image-does-not-matter-without-docker");core.start();assignments.start();
   teacher=new Control(core.port());String tLogin=teacher.login("teacher","Teacher123!");String tSession=session(tLogin);check(tSession!=null,"teacher authenticated on control port");
   teacher.send("/create");String room="";for(int i=0;i<8;i++){String msg=teacher.read();Matcher m=Pattern.compile("Đã tạo và tham gia phòng: (\\S+)").matcher(msg);if(m.find()){room=m.group(1);break;}}check(!room.isBlank(),"teacher creates a room");
   student1=new Control(core.port());String s1Session=session(student1.login("student1","Student123!"));student1.send("/join "+room);String joined="";for(int i=0;i<8;i++){String msg=student1.read();if(msg.contains("Đã tham gia phòng:")){joined=msg;break;}}check(!joined.isBlank(),"student1 joined same room");
   student2=new Control(core.port());String s2Session=session(student2.login("student2","Student234!"));student2.send("/join "+room);for(int i=0;i<8;i++){String msg=student2.read();if(msg.contains("Đã tham gia phòng:"))break;}
   Map<String,Object> roomStudents=call(assignments.port(),"ROOM_STUDENTS_LIST",tSession,room,Map.of());check(ok(roomStudents),"teacher can load the room student dropdown");List<Object> roomStudentRows=AssignmentJson.list(AssignmentJson.map(roomStudents.get("data")).get("students"));Set<String> roomStudentNames=new HashSet<>();for(Object row:roomStudentRows)roomStudentNames.add(AssignmentJson.text(AssignmentJson.map(row),"username",""));check(roomStudentNames.contains("student1")&&roomStudentNames.contains("student2")&&!roomStudentNames.contains("teacher"),"student dropdown contains only current room students");Map<String,Object> studentRoomStudents=call(assignments.port(),"ROOM_STUDENTS_LIST",s1Session,room,Map.of());check("FORBIDDEN".equals(studentRoomStudents.get("errorCode")),"student cannot enumerate teacher-only assignment targets");
   Map<String,Object> catalog=call(assignments.port(),"CATALOG_LIST",tSession,room,AssignmentJson.mapOf("query","DBG_ARR001","mode","DEBUG_COLLAB"));check(ok(catalog),"assignment channel validates active teacher session");Map<String,Object> cData=AssignmentJson.map(catalog.get("data"));List<Object> debugRows=AssignmentJson.list(cData.get("exercises"));check(!debugRows.isEmpty(),"mode-filtered catalog returns a debug exercise");check("DEBUG_COLLAB".equals(AssignmentJson.text(AssignmentJson.map(debugRows.get(0)),"mode","")),"catalog keeps explicit DEBUG_COLLAB mode");
   Map<String,Object> studentCatalog=call(assignments.port(),"CATALOG_LIST",s1Session,room,Map.of());check("FORBIDDEN".equals(studentCatalog.get("errorCode")),"student cannot enumerate the teacher-only exercise bank");
   Map<String,Object> catalogContest=call(assignments.port(),"CONTEST_CREATE",tSession,room,AssignmentJson.mapOf("title","Catalog-first exam","exerciseIds",List.of("ARR001"),"contestType","INDIVIDUAL","startInMinutes",0,"durationMinutes",10));check(ok(catalogContest),"teacher can create a contest directly from an unassigned catalog exercise");String catalogContestId=String.valueOf(AssignmentJson.map(catalogContest.get("data")).get("contestId"));
   Map<String,Object> contestProblems=call(assignments.port(),"CONTEST_PROBLEMS_GET",s1Session,room,Map.of("contestId",catalogContestId));check(ok(contestProblems),"student can load the public problems inside a contest");List<Object> contestProblemRows=AssignmentJson.list(AssignmentJson.map(contestProblems.get("data")).get("problems"));check(contestProblemRows.size()==1&&"ARR001".equals(AssignmentJson.text(AssignmentJson.map(contestProblemRows.get(0)),"id","")),"contest displays selected exercise straight from the catalog");
   Map<String,Object> debugCreate=call(assignments.port(),"ASSIGN_CREATE",tSession,room,AssignmentJson.mapOf("exerciseId","DBG_ARR001","scope","ROOM","deadlineMinutes",20));check(ok(debugCreate),"owner can assign a DEBUG_COLLAB task to the room");Map<String,Object> debugAssignment=AssignmentJson.map(AssignmentJson.map(debugCreate.get("data")).get("assignment"));String debugAid=String.valueOf(debugAssignment.get("id"));check("DEBUG_COLLAB".equals(debugAssignment.get("mode")),"assignment snapshots its exercise mode");
   Map<String,Object> individualDebug=call(assignments.port(),"ASSIGN_CREATE",tSession,room,AssignmentJson.mapOf("exerciseId","DBG_ARR001","scope","INDIVIDUAL","targetUsername","student1","deadlineMinutes",0));check("INVALID_REQUEST".equals(individualDebug.get("errorCode")),"DEBUG_COLLAB cannot be assigned individually");
   Map<String,Object> detail=call(assignments.port(),"ASSIGN_GET",s1Session,room,Map.of("assignmentId",debugAid));check(ok(detail),"student can view room debug assignment");Map<String,Object> detailData=AssignmentJson.map(detail.get("data"));Map<String,Object> exercise=AssignmentJson.map(AssignmentJson.map(detailData.get("assignment")).get("exercise"));check("DEBUG_COLLAB".equals(exercise.get("mode")),"assignment detail exposes exercise mode");check(!exercise.containsKey("referenceSolution"),"catalog does not expose reference solution");
   Map<String,Object> personalSubmitForDebug=call(assignments.port(),"SUBMIT_CREATE",s1Session,room,AssignmentJson.mapOf("assignmentId",debugAid,"submissionMode","PERSONAL","sourceCode","public class Main {}","idempotencyKey",UUID.randomUUID().toString()));check("INVALID_REQUEST".equals(personalSubmitForDebug.get("errorCode")),"debug assignment cannot create personal submission");
   Map<String,Object> prepare=call(assignments.port(),"DEBUG_STARTER_PREPARE",tSession,room,Map.of("assignmentId",debugAid));check(ok(prepare),"teacher can prepare debug starter load");Map<String,Object> prepData=AssignmentJson.map(prepare.get("data"));check(String.valueOf(prepData.get("starterCode")).contains("i<=n"),"debug starter contains intentionally buggy source");long version=AssignmentJson.number(prepData,"roomCodeVersion",-1);check(version>=0,"server exposes current shared room version");
   Map<String,Object> studentLoad=call(assignments.port(),"DEBUG_STARTER_LOAD",s1Session,room,AssignmentJson.mapOf("assignmentId",debugAid,"expectedVersion",version));check("FORBIDDEN".equals(studentLoad.get("errorCode")),"student cannot replace shared code with starter");
   Map<String,Object> loaded=call(assignments.port(),"DEBUG_STARTER_LOAD",tSession,room,AssignmentJson.mapOf("assignmentId",debugAid,"expectedVersion",version));check(ok(loaded),"teacher can load confirmed starter using expected version");long loadedVersion=AssignmentJson.number(AssignmentJson.map(loaded.get("data")),"roomCodeVersion",-1);check(loadedVersion>=version,"starter load returns committed room version");
   Map<String,Object> state=call(assignments.port(),"SHARED_CODE_STATE",s1Session,room,Map.of("assignmentId",debugAid));check(ok(state),"room student can query shared code state");Map<String,Object> stateData=AssignmentJson.map(state.get("data"));long checkVersion=AssignmentJson.number(stateData,"roomCodeVersion",-1);String hash=AssignmentJson.text(stateData,"sourceHash","");check(checkVersion==loadedVersion&&!hash.isBlank(),"shared state includes authoritative version and source hash");
   String checkKey=UUID.randomUUID().toString();Map<String,Object> checkReceipt=call(assignments.port(),"SHARED_CHECK_CREATE",s1Session,room,AssignmentJson.mapOf("assignmentId",debugAid,"checkRequestId",checkKey,"roomCodeVersion",checkVersion,"sourceHash",hash));check(ok(checkReceipt),"student can enqueue check of committed shared version");Map<String,Object> checkRun=AssignmentJson.map(AssignmentJson.map(checkReceipt.get("data")).get("checkRun"));String checkId=String.valueOf(checkRun.get("id"));check("QUEUED".equals(checkRun.get("status")),"shared check receipt reports queued state");check(AssignmentJson.number(checkRun,"checkedVersion",-1)==checkVersion,"shared check is bound to the checked version");check(!checkRun.containsKey("sourceCode")&&!checkRun.containsKey("sourceHash"),"shared check response does not expose stored source or internal hash");
   Map<String,Object> duplicate=call(assignments.port(),"SHARED_CHECK_CREATE",s1Session,room,AssignmentJson.mapOf("assignmentId",debugAid,"checkRequestId",checkKey,"roomCodeVersion",checkVersion,"sourceHash",hash));Map<String,Object> dupRun=AssignmentJson.map(AssignmentJson.map(duplicate.get("data")).get("checkRun"));check(ok(duplicate)&&checkId.equals(dupRun.get("id")),"retries with same checkRequestId return the same check run");
   Map<String,Object> stale=call(assignments.port(),"SHARED_CHECK_CREATE",s2Session,room,AssignmentJson.mapOf("assignmentId",debugAid,"checkRequestId",UUID.randomUUID().toString(),"roomCodeVersion",checkVersion-1,"sourceHash",hash));check("STALE_VERSION".equals(stale.get("errorCode")),"stale room version is rejected");
   Map<String,Object> wrongHash=call(assignments.port(),"SHARED_CHECK_CREATE",s2Session,room,AssignmentJson.mapOf("assignmentId",debugAid,"checkRequestId",UUID.randomUUID().toString(),"roomCodeVersion",checkVersion,"sourceHash","wrong-hash"));check("STALE_SOURCE".equals(wrongHash.get("errorCode")),"unverified source hash is rejected");
   Map<String,Object> otherRoomResult=call(assignments.port(),"SHARED_CHECK_RESULT",s2Session,room,Map.of("checkRunId",checkId));check(ok(otherRoomResult),"other member of same room can view group check status");Map<String,Object> finalCheck=null;for(int i=0;i<30;i++){Map<String,Object> poll=call(assignments.port(),"SHARED_CHECK_RESULT",s2Session,room,Map.of("checkRunId",checkId));if(!ok(poll))break;finalCheck=AssignmentJson.map(AssignmentJson.map(poll.get("data")).get("checkRun"));String st=AssignmentJson.text(finalCheck,"status","");if(!"QUEUED".equals(st)&&!"RUNNING".equals(st))break;Thread.sleep(100);}check(finalCheck!=null&&Set.of("PASS","FAILED","SANDBOX_UNAVAILABLE","INTERNAL_ERROR").contains(finalCheck.get("status")),"shared worker returns an explicit final state (PASS/FAILED or fail-closed infrastructure status)");check(finalCheck!=null&&AssignmentJson.number(finalCheck,"checkedVersion",-1)==checkVersion,"final group check result still names its checked version");
   Map<String,Object> scratchCreate=call(assignments.port(),"ASSIGN_CREATE",tSession,room,AssignmentJson.mapOf("exerciseId","ARR001","scope","ROOM","deadlineMinutes",20));check(ok(scratchCreate),"BUILD_FROM_SCRATCH assignment can be created");String scratchAid=String.valueOf(AssignmentJson.map(AssignmentJson.map(scratchCreate.get("data")).get("assignment")).get("id"));
   Map<String,Object> personalSubmit=call(assignments.port(),"SUBMIT_CREATE",s1Session,room,AssignmentJson.mapOf("assignmentId",scratchAid,"sourceCode","public class Main { public static void main(String[] args) { System.out.println(6); } }","idempotencyKey",UUID.randomUUID().toString()));check(ok(personalSubmit),"student can submit personal code for BUILD_FROM_SCRATCH");Map<String,Object> sub=AssignmentJson.map(AssignmentJson.map(personalSubmit.get("data")).get("submission"));String sid=String.valueOf(sub.get("id"));check("QUEUED".equals(sub.get("status"))&&"PERSONAL".equals(sub.get("submissionMode")),"personal receipt records queued state and PERSONAL mode");
   Map<String,Object> sharedAsPersonal=call(assignments.port(),"SUBMIT_CREATE",s2Session,room,AssignmentJson.mapOf("assignmentId",scratchAid,"submissionMode","SHARED_SNAPSHOT","sourceCode","public class Main {}","idempotencyKey",UUID.randomUUID().toString()));check("INVALID_REQUEST".equals(sharedAsPersonal.get("errorCode")),"SHARED_SNAPSHOT cannot be submitted as a personal submission");
   Map<String,Object> privateRead=call(assignments.port(),"SUBMISSION_RESULT",s2Session,room,Map.of("submissionId",sid));check("ERROR".equals(privateRead.get("status"))&&"FORBIDDEN".equals(privateRead.get("errorCode")),"another student cannot read private submission");
   Map<String,Object> result=null;for(int i=0;i<30;i++){result=call(assignments.port(),"SUBMISSION_RESULT",s1Session,room,Map.of("submissionId",sid));Map<String,Object> dat=AssignmentJson.map(result.get("data"));Map<String,Object> row=AssignmentJson.map(dat.get("submission"));if("DONE".equals(row.get("status")))break;Thread.sleep(100);}check(ok(result),"student can poll their personal result");Map<String,Object> r=AssignmentJson.map(AssignmentJson.map(result.get("data")).get("submission"));check("DONE".equals(r.get("status")),"personal worker exits QUEUED/RUNNING state");check(Set.of("SANDBOX_UNAVAILABLE","ACCEPTED","WRONG_ANSWER","COMPILE_ERROR","RUNTIME_ERROR","TIME_LIMIT_EXCEEDED","OUTPUT_LIMIT_EXCEEDED","MEMORY_LIMIT_EXCEEDED","INTERNAL_ERROR").contains(r.get("verdict")),"personal worker returns a documented verdict or fail-closed sandbox result");check(((Number)r.get("totalTests")).intValue()==3,"total test count remains visible when personal grading completes");
   Map<String,Object> contestSubmit=call(assignments.port(),"CONTEST_SUBMIT",s1Session,room,AssignmentJson.mapOf("contestId",catalogContestId,"exerciseId","ARR001","sourceCode","public class Main { public static void main(String[] args) { System.out.println(6); } }","idempotencyKey",UUID.randomUUID().toString()));check(ok(contestSubmit),"student can submit in a contest without an ordinary assignment");Map<String,Object> contestSubmission=AssignmentJson.map(AssignmentJson.map(contestSubmit.get("data")).get("submission"));String contestSubmissionId=String.valueOf(contestSubmission.get("id"));check("QUEUED".equals(contestSubmission.get("status")),"contest submission is independently queued for grading");
   Map<String,Object> privateContestRead=call(assignments.port(),"CONTEST_SUBMISSION_RESULT",s2Session,room,Map.of("submissionId",contestSubmissionId));check("FORBIDDEN".equals(privateContestRead.get("errorCode")),"another student cannot read a private contest submission");
   Map<String,Object> contestResult=null;for(int i=0;i<30;i++){contestResult=call(assignments.port(),"CONTEST_SUBMISSION_RESULT",s1Session,room,Map.of("submissionId",contestSubmissionId));if(!ok(contestResult))break;Map<String,Object> row=AssignmentJson.map(AssignmentJson.map(contestResult.get("data")).get("submission"));if("DONE".equals(row.get("status")))break;Thread.sleep(100);}check(ok(contestResult)&&"DONE".equals(AssignmentJson.text(AssignmentJson.map(AssignmentJson.map(contestResult.get("data")).get("submission")),"status","")),"contest submission worker returns a final grading state");
   Map<String,Object> teamContest=call(assignments.port(),"CONTEST_CREATE",tSession,room,AssignmentJson.mapOf("title","Team contest pending feature","exerciseIds",List.of("DBG_ARR001"),"contestType","TEAM_COLLAB","startInMinutes",0,"durationMinutes",10));check("CONTEST_TYPE_NOT_READY".equals(teamContest.get("errorCode")),"team contests are explicitly blocked until team scoring is implemented");
   Map<String,Object> debugContest=call(assignments.port(),"CONTEST_CREATE",tSession,room,AssignmentJson.mapOf("title","Debug contest should fail","assignmentIds",List.of(debugAid),"startInMinutes",0,"durationMinutes",10));check("INVALID_REQUEST".equals(debugContest.get("errorCode")),"contest rejects DEBUG_COLLAB as an individual contest");
   Map<String,Object> contest=call(assignments.port(),"CONTEST_CREATE",tSession,room,AssignmentJson.mapOf("title","Personal coding contest","assignmentIds",List.of(scratchAid),"startInMinutes",0,"durationMinutes",10));check(ok(contest),"contest accepts BUILD_FROM_SCRATCH assignment");
   Map<String,Object> individ=call(assignments.port(),"ASSIGN_CREATE",tSession,room,AssignmentJson.mapOf("exerciseId","STR001","scope","INDIVIDUAL","targetUsername","student1","deadlineMinutes",0));check(ok(individ),"teacher can target a current room member individually");String indId=String.valueOf(AssignmentJson.map(AssignmentJson.map(individ.get("data")).get("assignment")).get("id"));Map<String,Object> s2detail=call(assignments.port(),"ASSIGN_GET",s2Session,room,Map.of("assignmentId",indId));check("FORBIDDEN".equals(s2detail.get("errorCode")),"individual assignment hidden from other students");
   Map<String,Object> progress=call(assignments.port(),"CLASS_PROGRESS",tSession,room,Map.of());check(ok(progress),"teacher can load class progress report");List<Object> progressRows=AssignmentJson.list(AssignmentJson.map(progress.get("data")).get("assignments"));Map<String,Object> scratchProgress=null;for(Object o:progressRows){Map<String,Object> row=AssignmentJson.map(o);if(scratchAid.equals(AssignmentJson.text(row,"assignmentId","")))scratchProgress=row;}check(scratchProgress!=null&&AssignmentJson.number(scratchProgress,"receivedCount",0)>=2,"class report includes assignment recipients and counts");List<Object> studentProgress=AssignmentJson.list(scratchProgress.get("entries"));check(studentProgress.stream().map(AssignmentJson::map).anyMatch(m->"student1".equals(AssignmentJson.text(m,"username",""))),"class report drills down by student");check(studentProgress.stream().map(AssignmentJson::map).noneMatch(m->m.containsKey("sourceCode")||m.containsKey("referenceSolution")),"class progress summary omits source code and reference solution");Map<String,Object> studentProgressDenied=call(assignments.port(),"CLASS_PROGRESS",s1Session,room,Map.of());check("FORBIDDEN".equals(studentProgressDenied.get("errorCode")),"students cannot access class progress reports");
   System.out.println("AssignmentProtocolIntegrationTest PASS: "+checks+" checks (grading verdict reports Docker availability)");
  }finally{if(student2!=null)student2.close();if(student1!=null)student1.close();if(teacher!=null)teacher.close();if(assignments!=null)assignments.close();if(core!=null)core.close();try(var w=Files.walk(temp)){w.sorted(Comparator.reverseOrder()).forEach(p->{try{Files.deleteIfExists(p);}catch(Exception ignored){}});}}
 }
 private static boolean ok(Map<String,Object> m){return "OK".equals(m.get("status"));}
 private static String session(String response){Matcher m=Pattern.compile("session=([^ ]+)").matcher(response);return m.find()?m.group(1):null;}
 private static Map<String,Object> call(int port,String type,String session,String room,Map<String,Object> fields)throws Exception{Map<String,Object> req=new LinkedHashMap<>(fields);req.put("type",type);req.put("requestId",UUID.randomUUID().toString());req.put("sessionId",session);req.put("roomId",room);req.put("protocolVersion",1);try(Socket s=new Socket("127.0.0.1",port)){s.setSoTimeout(5000);DataOutputStream out=new DataOutputStream(new BufferedOutputStream(s.getOutputStream()));DataInputStream in=new DataInputStream(new BufferedInputStream(s.getInputStream()));AssignmentWire.write(out,AssignmentJson.stringify(req));return AssignmentJson.object(AssignmentWire.read(in));}}
 private static final class Control implements AutoCloseable{final Socket s;final DataInputStream in;final DataOutputStream out;Control(int port)throws Exception{s=new Socket("127.0.0.1",port);s.setSoTimeout(5000);in=new DataInputStream(new BufferedInputStream(s.getInputStream()));out=new DataOutputStream(new BufferedOutputStream(s.getOutputStream()));}String login(String u,String p)throws Exception{send("/login "+u+" "+p);return read();}void send(String cmd)throws Exception{Protocol.send(out,cmd);}String read()throws Exception{return Protocol.receive(in);}@Override public void close(){try{s.close();}catch(Exception ignored){}}}
}
